// <diletta-tooltip> — a INSTÂNCIA WEB de `design-system-tooltip`.
//
// A pintura vem de `pintura.g.js` (tabela medida no render do Dart). `side` e
// `size` não estão lá porque não são cor — eles são geometria, e a spec não
// declara token de geometria para esta peça: o que está aqui é estrutura mínima,
// e está marcado como tal.
import { papeisDe, estiloDa, eixo } from './base.js';

const SLUG = 'design-system-tooltip';
const STYLE = ['dark', 'light'];
const TONE = ['normal', 'error'];
const SIDE = ['top', 'right', 'bottom', 'left'];
const SIZE = ['big', 'small', 'xsmall'];

// A seta aponta PARA o alvo, então ela mora no lado oposto ao `side`: um tooltip
// em `top` fica acima e a seta desce.
const OPOSTO = { top: 'bottom', bottom: 'top', left: 'right', right: 'left' };

class DilettaTooltip extends HTMLElement {
  static observedAttributes = ['style-tooltip', 'tone', 'side', 'size', 'texto'];

  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
  }

  connectedCallback() {
    this.render();
  }

  attributeChangedCallback() {
    if (this.shadowRoot) this.render();
  }

  render() {
    // `style` é atributo global do HTML e já significa CSS inline. Usar aquele nome
    // para um eixo do DS sequestraria o atributo nativo — daí `style-tooltip`.
    const estilo = eixo(this, 'style-tooltip', STYLE, 'dark');
    const tone = eixo(this, 'tone', TONE, 'normal');
    const side = eixo(this, 'side', SIDE, 'top');
    const size = eixo(this, 'size', SIZE, 'small');
    const papeis = papeisDe(SLUG, { Style: estilo, Tone: tone });

    // A spec: *"o tom GANHA do estilo"* — com `error`, fundo `error` e letra
    // `onError` NOS DOIS estilos. Não está implementado aqui: está na TABELA, e é
    // por isso que a regra não pode divergir entre as duas instâncias.
    const respiro = { big: '12px 16px', small: '8px 12px', xsmall: '6px 8px' }[size];

    this.shadowRoot.innerHTML = `
      <style>
        :host { display: inline-block; position: relative; }
        .balao {
          /* A SETA ancora no BALÃO, e por isso ele precisa ser o bloco posicionado.
             Sem isto ela cai no host e, com side=left, aparece descolada a
             centenas de pixels do balão. Nenhum teste pegou: os dois estavam no
             DOM, com os atributos certos, e só o layout mostrava. Foi o print. */
          position: relative;
          ${estiloDa(papeis)}
          box-sizing: border-box;
          padding: ${respiro};
          border-radius: 8px;
          max-width: 240px;
          font-size: var(--cps-type-caption-size, 12px);
          line-height: var(--cps-type-caption-line-height, 16px);
          font-weight: var(--cps-type-caption-weight, 400);
        }
        .seta {
          position: absolute; width: 8px; height: 8px;
          background: inherit;
          transform: rotate(45deg);
        }
        .balao[data-seta="bottom"] .seta { bottom: -4px; left: calc(50% - 4px); }
        .balao[data-seta="top"]    .seta { top: -4px;    left: calc(50% - 4px); }
        .balao[data-seta="left"]   .seta { left: -4px;   top: calc(50% - 4px); }
        .balao[data-seta="right"]  .seta { right: -4px;  top: calc(50% - 4px); }
      </style>
      <div class="balao" role="tooltip" data-seta="${OPOSTO[side]}">
        <span class="seta" aria-hidden="true"></span><slot>${this.getAttribute('texto') || ''}</slot>
      </div>`;
  }
}

customElements.define('diletta-tooltip', DilettaTooltip);
export { DilettaTooltip };
